30	} from '@/features/financeiro/model/useCmvGraph';
31	import { layoutGraph } from '@/components/producao/configurador/layout';
32	import { toast } from 'sonner';
33	import {
34	  ArrowLeft,
35	  LayoutTemplate,
36	  Plus,
37	  Save,
38	  Trash2,
39	  Package,
40	  DollarSign,
41	  Loader2,
42	  Calculator,
43	  ChefHat,
44	  Wheat,
45	  Receipt,
46	} from 'lucide-react';
47	import { Button } from '@/shared/ui/button';
48	import { Input } from '@/shared/ui/input';
49	import { Label } from '@/shared/ui/label';
50	import {
51	  Sheet,
52	  SheetContent,
53	  SheetHeader,
54	  SheetTitle,
55	  SheetFooter,
56	} from '@/shared/ui/sheet';
57	import {
58	  Dialog,
59	  DialogContent,
60	  DialogHeader,
61	  DialogTitle,
62	  DialogFooter,
63	} from '@/shared/ui/dialog';
64	import {
65	  Select,
66	  SelectContent,
67	  SelectItem,
68	  SelectTrigger,
69	  SelectValue,
70	} from '@/shared/ui/select';
71	
72	// ---------------------------------------------------------------------------
73	// HELPERS
74	// ---------------------------------------------------------------------------
75	
76	const fmt = (v: number | null | undefined): string => {
77	  if (typeof v !== 'number') return 'R$ 0,00';
78	  return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
79	};
80	
81	type TipoItem = 'embalagem' | 'outro';
82	
83	const TIPO_CONFIG: Record<TipoItem, { label: string; color: string; border: string; icon: React.ReactNode }> = {
84	  embalagem: {
85	    label: 'Embalagem',
86	    color: 'bg-blue-600/80',
87	    border: 'border-blue-400/40',
88	    icon: <Package size={12} />,
89	  },
90	  outro: {
91	    label: 'Custo avulso',
92	    color: 'bg-orange-700/60',
93	    border: 'border-dashed border-orange-400/60',
94	    icon: <DollarSign size={12} />,
95	  },
96	};
97	
98	const STATUS_COLORS: Record<string, string> = {
99	  rascunho: 'bg-zinc-200/80 text-zinc-700 dark:bg-zinc-700 dark:text-zinc-300',
100	  aprovada: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-800/60 dark:text-emerald-300',
101	  obsoleta: 'bg-zinc-200/80 text-zinc-500 dark:bg-zinc-800 dark:text-zinc-500',
102	};
103	
104	// ---------------------------------------------------------------------------
105	// CUSTOM NODE COMPONENTS
106	// ---------------------------------------------------------------------------
107	
108	interface CmvRootNodeData extends Record<string, unknown> {
109	  nome: string;
110	  custo: number | null;
111	  status: string;
112	}
113	
114	const CmvRootNode = memo(function CmvRootNode({ data }: NodeProps<CmvRootNodeData>) {
115	  return (
116	    <div className="relative px-5 py-4 rounded-2xl border border-[#57715B]/50 bg-[#57715B]/90 backdrop-blur-md text-white min-w-[260px] shadow-2xl shadow-[#57715B]/40">
117	      <div className="flex items-start justify-between mb-2 gap-2">
118	        <div className="flex items-center gap-1.5 opacity-80">
119	          <Calculator size={12} />
120	          <span className="text-[9px] font-bold uppercase tracking-wider">CMV Central</span>
121	        </div>
122	        <span className={`text-[9px] px-2 py-0.5 rounded-full font-bold uppercase tracking-wide ${STATUS_COLORS[data.status] ?? STATUS_COLORS.rascunho}`}>
123	          {data.status}
124	        </span>
125	      </div>
126	      <h3 className="text-base font-bold truncate leading-tight mb-2">{data.nome}</h3>
127	      <p className="text-2xl font-black tabular-nums">{fmt(data.custo)}</p>
128	      <Handle type="target" position={Position.Left} className="!w-3.5 !h-3.5 !bg-white/60 !border-2 !border-white/30" />
129	    </div>
130	  );
131	});
132	
133	interface FichaBaseNodeData extends Record<string, unknown> {
134	  nome: string;
135	  custoUnitario: number;
136	  rendimento: string;
137	  status: string;
138	}
139	
140	const FichaBaseNode = memo(function FichaBaseNode({ data }: NodeProps<FichaBaseNodeData>) {
141	  return (
142	    <div className="relative px-5 py-4 rounded-2xl border border-amber-500/40 bg-amber-700/80 backdrop-blur-md text-white min-w-[240px] shadow-xl shadow-amber-700/30">
143	      <div className="flex items-center gap-1.5 opacity-80 mb-2">
144	        <ChefHat size={12} />
145	        <span className="text-[9px] font-bold uppercase tracking-wider">Ficha Técnica Base</span>
146	      </div>
147	      <h3 className="text-base font-semibold truncate mb-1">{data.nome}</h3>
148	      <div className="flex items-end justify-between mt-2">
149	        <div>
150	          <p className="text-[9px] opacity-60 leading-none mb-0.5">Custo unitário</p>
151	          <p className="text-xl font-bold tabular-nums">{fmt(data.custoUnitario)}</p>
152	        </div>
153	        <span className="text-[10px] px-2 py-0.5 bg-white/20 rounded-full">{data.rendimento}</span>
154	      </div>
155	      <Handle type="source" position={Position.Right} className="!w-3 !h-3 !bg-amber-300 !border-2 !border-white" />
156	    </div>
157	  );
158	});
159	
160	interface CmvItemNodeData extends Record<string, unknown> {
161	  tipo: TipoItem;
162	  quantidade: number;
163	  unidade: string;
164	  custo: number | null;
165	  label: string;
166	}
167	
168	const CmvItemNode = memo(function CmvItemNode({ data, selected }: NodeProps<CmvItemNodeData>) {
169	  const cfg = TIPO_CONFIG[data.tipo as TipoItem] ?? TIPO_CONFIG.outro;
170	  return (
171	    <div className={`relative px-4 py-3 rounded-xl border backdrop-blur-md text-zinc-100 min-w-[200px] shadow-lg transition-all duration-150 ${cfg.color} ${cfg.border} ${selected ? 'ring-2 ring-white/40 scale-[1.02]' : 'hover:shadow-xl hover:-translate-y-0.5'}`}>
172	      <div className="flex items-center gap-1.5 mb-2">
173	        <span className="opacity-80">{cfg.icon}</span>
174	        <span className="text-[9px] font-bold uppercase tracking-wider opacity-80">{cfg.label}</span>
175	      </div>
176	      <h4 className="text-sm font-semibold truncate mb-1.5">{data.label}</h4>
177	      <div className="flex items-end justify-between">
178	        <span className="text-[11px] text-white/70">{data.quantidade} {data.unidade}</span>
179	        <span className="text-base font-bold tabular-nums">{fmt(data.custo)}</span>
180	      </div>
181	      <Handle type="target" position={Position.Left} className="!w-2.5 !h-2.5 !bg-white/40 !border-2 !border-white/20" />
182	      <Handle type="source" position={Position.Right} className="!w-2.5 !h-2.5 !bg-white/60 !border-2 !border-white/30" />
183	    </div>
184	  );
185	});
186	
187	interface InsumoNodeData extends Record<string, unknown> {
188	  nome: string;
189	  preco: number | null;
190	  unidade: string;
191	}
192	
193	const InsumoNode = memo(function InsumoNode({ data }: NodeProps<InsumoNodeData>) {
194	  return (
195	    <div className="px-3 py-2 rounded-lg border border-violet-400/30 bg-violet-700/70 backdrop-blur-sm text-white min-w-[180px] shadow-md">
196	      <div className="flex items-center gap-1 mb-1 opacity-70">
197	        <Wheat size={10} />
198	        <span className="text-[9px] font-bold uppercase">Insumo</span>
199	      </div>
200	      <h4 className="text-xs font-semibold truncate">{data.nome}</h4>
201	      <p className="text-sm font-bold tabular-nums">
202	        {fmt(data.preco)} <span className="text-[9px] font-normal opacity-60">/{data.unidade}</span>
203	      </p>
204	      <Handle type="source" position={Position.Right} className="!w-2 !h-2 !bg-violet-300 !border-2 !border-white" />
205	    </div>
206	  );
207	});
208	
209	interface NFNodeData extends Record<string, unknown> {
210	  fornecedor: string;
211	  numero: string | null;
212	  valor: number | null;
213	}
214	
215	const NFNode = memo(function NFNode({ data }: NodeProps<NFNodeData>) {
216	  return (
217	    <div className="px-3 py-2 rounded-lg border border-cyan-400/30 bg-cyan-700/70 backdrop-blur-sm text-white min-w-[160px] shadow-md">
218	      <div className="flex items-center gap-1 mb-1 opacity-70">
219	        <Receipt size={10} />
220	        <span className="text-[9px] font-bold uppercase">Nota Fiscal</span>
221	      </div>
222	      <h4 className="text-[11px] font-semibold truncate">{data.fornecedor || 'Fornecedor'}</h4>
223	      {data.numero && <p className="text-[9px] opacity-60">#{data.numero}</p>}
224	      <p className="text-xs font-bold tabular-nums">{fmt(data.valor)}</p>
225	      <Handle type="source" position={Position.Right} className="!w-2 !h-2 !bg-cyan-300 !border-2 !border-white" />
226	    </div>
227	  );
228	});
229	
230	const nodeTypes: NodeTypes = {
231	  cmv: CmvRootNode,
232	  ficha: FichaBaseNode,
233	  cmvItem: CmvItemNode,
234	  insumo: InsumoNode,
235	  nf: NFNode,
236	};
237	
238	// ---------------------------------------------------------------------------
239	// INNER COMPONENT (usa useReactFlow())
240	// ---------------------------------------------------------------------------
241	
242	function CmvConfiguratorInner() {
243	  const navigate = useNavigate();
244	  const [searchParams] = useSearchParams();
245	  const cmvIdParam = searchParams.get('focus');
246	  const cmvId = cmvIdParam !== null && cmvIdParam !== '' ? parseInt(cmvIdParam, 10) : null;
247	
248	  const {
249	    loading,
250	    cmv,
251	    fichaData,
252	    items,
253	    insumos,
254	    positions,
255	    savePosition,
256	    refetch,
257	  } = useCmvGraph(cmvId);
258	
259	  const { fitView } = useReactFlow();
260	  const queryClient = useQueryClient();
261	  const [nodes, setNodes, onNodesChange] = useNodesState([]);
262	  const [edges, setEdges, onEdgesChange] = useEdgesState([]);
263	
264	  // Detail panel state
265	  const [selectedItemData, setSelectedItemData] = useState<RawCmvItem | null>(null);
266	  const [editQty, setEditQty] = useState('');
267	  const [editUnit, setEditUnit] = useState('');
268	  const [editPreco, setEditPreco] = useState('');
269	  const [editObs, setEditObs] = useState('');
270	  const [isSaving, setIsSaving] = useState(false);
271	  const [isDeleting, setIsDeleting] = useState(false);
272	
273	  // Add item dialog state
274	  const [isAddOpen, setIsAddOpen] = useState(false);
275	  const [newTipo, setNewTipo] = useState<TipoItem>('embalagem');
276	  const [newInsumoId, setNewInsumoId] = useState<string>('');
277	  const [newQty, setNewQty] = useState('1');
278	  const [newUnit, setNewUnit] = useState('un');
279	  const [newPreco, setNewPreco] = useState('');
280	  const [newObs, setNewObs] = useState('');
281	  const [isAddSaving, setIsAddSaving] = useState(false);
282	
283	  // -------------------------------------------------------------------------
284	  // Build ReactFlow nodes/edges from hook data
285	  // -------------------------------------------------------------------------
286	  const buildGraph = useCallback(() => {
287	    if (!cmv) return;
288	
289	    const newNodes: Node[] = [];
290	    const newEdges: Edge[] = [];
291	
292	    const rootId = cmvNodeId(cmv.id);
293	
294	    // Root node
295	    newNodes.push({
296	      id: rootId,
297	      type: 'cmv',
298	      data: { nome: cmv.nome, custo: cmv.custo_calculado, status: cmv.status, kind: 'cmv' } as Record<string, unknown>,
299	      position: positions.get(rootId) ?? { x: 800, y: 300 },
300	    });
301	
302	    // Ficha base node
303	    if (fichaData) {
304	      const fId = fichaNodeId(fichaData.id);
305	      const rendQty = fichaData.rendimento_quantidade || 1;
306	      const custoUnitario = (fichaData.custo_calculado ?? 0) / rendQty;
307	
308	      newNodes.push({
309	        id: fId,
310	        type: 'ficha',
311	        data: {
312	          nome: fichaData.nome,
313	          custoUnitario,
314	          rendimento: `${fichaData.rendimento_quantidade} ${fichaData.rendimento_unidade}`,
315	          status: fichaData.status,
316	          kind: 'ficha',
317	        } as Record<string, unknown>,
318	        position: positions.get(fId) ?? { x: 400, y: 300 },
319	      });
320	
321	      newEdges.push({
322	        id: `e-${fId}-${rootId}`,
323	        source: fId,
324	        target: rootId,
325	        animated: true,
326	        style: { stroke: '#F59E0B', strokeWidth: 3 },
327	      });
328	    }
329	
330	    // Item nodes
331	    const addedInsumoIds = new Set<number>();
332	
333	    items.forEach((item, idx) => {
334	      const itemId = `item_${item.id}`;
335	      const label = item.insumo?.nome ?? item.observacao ?? `Item ${idx + 1}`;
336	
337	      newNodes.push({
338	        id: itemId,
339	        type: 'cmvItem',
340	        data: {
341	          tipo: item.tipo as TipoItem,
342	          quantidade: item.quantidade,
343	          unidade: item.unidade,
344	          custo: item.custo_calculado,
345	          label,
346	          kind: 'cmvItem',
347	          _rawItemId: item.id,
348	        } as Record<string, unknown>,
349	        position: positions.get(itemId) ?? { x: 400, y: 100 + idx * 160 },
350	      });
351	
352	      newEdges.push({
353	        id: `e-${itemId}-${rootId}`,
354	        source: itemId,
355	        target: rootId,
356	        style: { stroke: '#52525b', strokeWidth: 2 },
357	      });
358	
359	      // Insumo linked to item
360	      if (item.insumo_id && !addedInsumoIds.has(item.insumo_id)) {
361	        addedInsumoIds.add(item.insumo_id);
362	        const insId = insumoNodeId(item.insumo_id);
363	        const insData = insumos.find((i) => i.id === item.insumo_id);
364	
365	        newNodes.push({
366	          id: insId,
367	          type: 'insumo',
368	          data: {
369	            nome: insData?.nome ?? 'Insumo',
370	            preco: insData?.preco_custo ?? null,
371	            unidade: insData?.unidade_compra ?? 'un',
372	            kind: 'insumo',
373	          } as Record<string, unknown>,
374	          position: positions.get(insId) ?? { x: 100, y: 100 + idx * 160 },
375	        });
376	
377	        newEdges.push({
378	          id: `e-${insId}-${itemId}`,
379	          source: insId,
380	          target: itemId,
381	          style: { stroke: '#7c3aed', strokeWidth: 1.5 },
382	        });
383	      }
384	    });
385	
386	    // Apply dagre layout for nodes without saved positions
387	    const hasAllPositions = newNodes.every((n) => positions.has(n.id));
388	    if (!hasAllPositions && newNodes.length > 0) {
389	      const laid = layoutGraph(newNodes, newEdges, 'LR');
390	      setNodes(laid);
391	    } else {
392	      setNodes(newNodes);
393	    }
394	    setEdges(newEdges);
395	
396	    setTimeout(() => {
397	      fitView({ padding: 0.12, duration: 400 });
398	    }, 80);
399	  }, [cmv, fichaData, items, insumos, positions, fitView, setNodes, setEdges]);
400	
401	  useEffect(() => {
402	    if (!loading) {
403	      buildGraph();
404	    }
405	  }, [loading, buildGraph]);
406	
407	  // -------------------------------------------------------------------------
408	  // Node drag → save position
409	  // -------------------------------------------------------------------------
410	  const handleNodeDragStop: NodeDragHandler = useCallback(
411	    (_evt, node) => {
412	      savePosition(node.id, node.position.x, node.position.y);
413	    },
414	    [savePosition],
415	  );
416	
417	  // -------------------------------------------------------------------------
418	  // Node click → open detail panel
419	  // -------------------------------------------------------------------------
420	  const handleNodeClick = useCallback(
421	    (_evt: React.MouseEvent, node: Node) => {
422	      const rawId = (node.data as Record<string, unknown>)._rawItemId;
423	      if (typeof rawId !== 'number') {
424	        setSelectedItemData(null);
425	        return;
426	      }
427	      const found = items.find((it) => it.id === rawId);
428	      if (found) {
429	        setSelectedItemData(found);
430	        setEditQty(String(found.quantidade));
431	        setEditUnit(found.unidade);
432	        setEditPreco(found.preco_unitario_esboco !== null ? String(found.preco_unitario_esboco) : '');
433	        setEditObs(found.observacao ?? '');
434	      }
435	    },
436	    [items],
437	  );
438	
439	  // -------------------------------------------------------------------------
440	  // Auto-layout
441	  // -------------------------------------------------------------------------
442	  const handleAutoLayout = useCallback(() => {
443	    setNodes((prev) => {
444	      const laid = layoutGraph(prev, edges, 'LR');
445	      laid.forEach((n) => savePosition(n.id, n.position.x, n.position.y));
446	      return laid;
447	    });
448	    setTimeout(() => fitView({ padding: 0.12, duration: 400 }), 80);
449	  }, [edges, fitView, savePosition, setNodes]);
450	
451	  // -------------------------------------------------------------------------
452	  // Save item
453	  // -------------------------------------------------------------------------
454	  const handleSaveItem = useCallback(async () => {
455	    if (!selectedItemData) return;
456	    setIsSaving(true);
457	
458	    const updatePayload: Record<string, unknown> = {
459	      quantidade: parseFloat(editQty) || selectedItemData.quantidade,
460	      unidade: editUnit,
461	    };
462	    if (selectedItemData.tipo === 'outro') {
463	      updatePayload.preco_unitario_esboco = editPreco !== '' ? parseFloat(editPreco) : null;
464	      updatePayload.observacao = editObs.trim() || null;
465	    }
466	
467	    const { error } = await supabase
468	      .from('cmv_itens')
469	      .update(updatePayload)
470	      .eq('id', selectedItemData.id);
471	
472	    if (error) {
473	      toast.error(`Erro ao salvar: ${error.message}`);
474	    } else {
475	      toast.success('Item atualizado!');
476	      setSelectedItemData(null);
477	      await refetch();
478	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
479	    }
480	    setIsSaving(false);
481	  }, [selectedItemData, editQty, editUnit, editPreco, editObs, refetch, queryClient]);
482	
483	  // -------------------------------------------------------------------------
484	  // Delete item
485	  // -------------------------------------------------------------------------
486	  const handleDeleteItem = useCallback(async () => {
487	    if (!selectedItemData) return;
488	    setIsDeleting(true);
489	    const { error } = await supabase
490	      .from('cmv_itens')
491	      .delete()
492	      .eq('id', selectedItemData.id);
493	
494	    if (error) {
495	      toast.error(`Erro ao excluir: ${error.message}`);
496	    } else {
497	      toast.success('Item removido!');
498	      setSelectedItemData(null);
499	      await refetch();
500	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
501	    }
502	    setIsDeleting(false);
503	  }, [selectedItemData, refetch, queryClient]);
504	
505	  // -------------------------------------------------------------------------
506	  // Add item
507	  // -------------------------------------------------------------------------
508	  const handleAddItem = useCallback(async () => {
509	    if (!cmvId) return;
510	
511	    if (newTipo === 'embalagem' && !newInsumoId) {
512	      toast.error('Selecione um insumo para o item de embalagem.');
513	      return;
514	    }
515	    if (newTipo === 'outro' && newObs.trim() === '') {
516	      toast.error('Informe o nome do custo avulso no campo Observação.');
517	      return;
518	    }
519	
520	    setIsAddSaving(true);
521	
522	    const payload: Record<string, unknown> = {
523	      cmv_id: cmvId,
524	      tipo: newTipo,
525	      quantidade: parseFloat(newQty) || 1,
526	      unidade: newUnit,
527	      ordem: items.length,
528	    };
529	
530	    if (newTipo === 'embalagem') {
531	      payload.insumo_id = parseInt(newInsumoId, 10);
532	    } else {
533	      // outro: custo avulso
534	      payload.observacao = newObs.trim();
535	      payload.preco_unitario_esboco = newPreco !== '' ? parseFloat(newPreco) : null;
536	    }
537	
538	    const { error } = await supabase.from('cmv_itens').insert(payload);
539	
540	    if (error) {
541	      toast.error(`Erro ao criar item: ${error.message}`);
542	    } else {
543	      toast.success('Item adicionado!');
544	      setIsAddOpen(false);
545	      setNewTipo('embalagem');
546	      setNewInsumoId('');
547	      setNewQty('1');
548	      setNewUnit('un');
549	      setNewPreco('');
550	      setNewObs('');
551	      await refetch();
552	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
553	    }
554	    setIsAddSaving(false);
555	  }, [cmvId, newTipo, newInsumoId, newQty, newUnit, newPreco, newObs, items.length, refetch, queryClient]);
556	
557	  // -------------------------------------------------------------------------
558	  // Empty/loading states
559	  // -------------------------------------------------------------------------
560	  if (!cmvId) {
561	    return (
562	      <div className="h-[100dvh] bg-slate-50 dark:bg-slate-950 flex flex-col items-center justify-center text-muted-foreground">
563	        <Calculator className="h-12 w-12 mb-4 text-[#57715B]" />
564	        <p className="text-sm mb-4">Nenhum CMV selecionado</p>
565	        <Button variant="outline" className="rounded-xl border-[#57715B]/20 bg-white/60 hover:bg-[#57715B]/10 text-[#57715B]" onClick={() => navigate('/financeiro/cmv')}>
566	          <ArrowLeft className="mr-2 h-4 w-4" />
567	          Voltar ao CMV
568	        </Button>
569	      </div>
