84	interface CmvGraphData {
85	  loading: boolean;
86	  cmv: RawCmv | null;
87	  fichaData: RawCmvFicha | null;
88	  items: RawCmvItem[];
89	  insumos: RawCmvInsumo[];
90	  notas: RawCmvNF[];
91	  nfItems: RawCmvNFItem[];
92	  positions: Map<string, { x: number; y: number }>;
93	  savePosition: (key: string, x: number, y: number) => Promise<void>;
94	  refetch: () => Promise<void>;
95	}
